import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    // Trata números negativos se necessário, mas aqui são todos positivos
                } else {
                    res = res * 10 + (c - '0');
                }
                c = read();
            }
            return res;
        }
    }

    // Estrutura de lista de adjacência (Forward Star)
    static int[] head;
    static int[] to;
    static int[] next;
    static int[] weight;
    static int edgeCount = 0;

    static void addEdge(int u, int v, int w) {
        to[edgeCount] = v;
        weight[edgeCount] = w;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        int[] p = new int[k + 1];
        for (int i = 1; i <= k; i++) {
            p[i] = scanner.nextInt();
        }

        int[] edgeU = new int[m];
        int[] edgeV = new int[m];
        int[] edgeT = new int[m];

        // Lista de incidentes para encontrar os pares distintos (u, t)
        // Cada aresta gera duas extremidades (u, t) e (v, t)
        long[] endpoints = new long[2 * m];
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int t = scanner.nextInt();
            edgeU[i] = u;
            edgeV[i] = v;
            edgeT[i] = t;

            endpoints[2 * i] = ((long) u << 32) | t;
            endpoints[2 * i + 1] = ((long) v << 32) | t;
        }

        int startStation = scanner.nextInt();
        int endStation = scanner.nextInt();

        Arrays.sort(endpoints);
        int uniqueEndpointsCount = 0;
        for (int i = 0; i < endpoints.length; i++) {
            if (i == 0 || endpoints[i] != endpoints[i - 1]) {
                uniqueEndpointsCount++;
            }
        }

        long[] uniqueEndpoints = new long[uniqueEndpointsCount];
        int idx = 0;
        for (int i = 0; i < endpoints.length; i++) {
            if (i == 0 || endpoints[i] != endpoints[i - 1]) {
                uniqueEndpoints[idx++] = endpoints[i];
            }
        }

        // Nós do grafo auxiliar:
        // 1 .. n: estações
        // n + 1 .. n + uniqueEndpointsCount: pares (u, t)
        int totalNodes = n + uniqueEndpointsCount;

        // Número máximo de arestas:
        // uniqueEndpointsCount * 2 (para ligar estação <-> (estação, t))
        // + 2 * m (para cada aresta bidirecional entre (u, t) e (v, t))
        int maxEdges = 2 * uniqueEndpointsCount + 2 * m;

        head = new int[totalNodes + 1];
        Arrays.fill(head, -1);
        to = new int[maxEdges];
        next = new int[maxEdges];
        weight = new int[maxEdges];
        edgeCount = 0;

        // Conectar estações com seus respectivos (u, t)
        for (int i = 0; i < uniqueEndpointsCount; i++) {
            long key = uniqueEndpoints[i];
            int u = (int) (key >>> 32);
            int t = (int) (key & 0xFFFFFFFFL);
            int nodeUT = n + 1 + i;

            // u -> (u, t) com custo p[t]
            addEdge(u, nodeUT, p[t]);
            // (u, t) -> u com custo 0
            addEdge(nodeUT, u, 0);
        }

        // Conectar as arestas de transporte (u, t) <-> (v, t)
        for (int i = 0; i < m; i++) {
            int u = edgeU[i];
            int v = edgeV[i];
            int t = edgeT[i];

            long keyU = ((long) u << 32) | t;
            long keyV = ((long) v << 32) | t;

            int nodeU = n + 1 + Arrays.binarySearch(uniqueEndpoints, keyU);
            int nodeV = n + 1 + Arrays.binarySearch(uniqueEndpoints, keyV);

            addEdge(nodeU, nodeV, 0);
            addEdge(nodeV, nodeU, 0);
        }

        // Algoritmo de Dijkstra
        int[] dist = new int[totalNodes + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[startStation] = 0;

        // PriorityQueue armazenando (dist << 32) | node
        PriorityQueue<Long> pq = new PriorityQueue<>();
        pq.add(((long) 0 << 32) | startStation);

        while (!pq.isEmpty()) {
            long cur = pq.poll();
            int d = (int) (cur >>> 32);
            int u = (int) (cur & 0xFFFFFFFFL);

            if (d > dist[u]) continue;
            if (u == endStation) break;

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                int w = weight[e];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.add(((long) dist[v] << 32) | v);
                }
            }
        }

        if (dist[endStation] == Integer.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.println(dist[endStation]);
        }
    }
}
